CREATE TABLE IF NOT EXISTS exercise_catalog (
    id                 UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id    UUID         REFERENCES organizations(id) ON DELETE CASCADE,
    created_by_user_id UUID         REFERENCES users(id) ON DELETE SET NULL,
    external_source    VARCHAR(50)  NOT NULL DEFAULT 'custom',
    external_id        VARCHAR(120),
    name_pt            VARCHAR(255) NOT NULL,
    name_en            VARCHAR(255) NOT NULL DEFAULT '',
    primary_muscle     VARCHAR(50)  NOT NULL,
    secondary_muscles  JSONB        NOT NULL DEFAULT '[]'::jsonb,
    equipment          VARCHAR(50)  NOT NULL DEFAULT 'body only',
    category           VARCHAR(50)  NOT NULL DEFAULT 'strength',
    level              VARCHAR(30)  NOT NULL DEFAULT 'intermediate',
    force              VARCHAR(30)  NOT NULL DEFAULT '',
    mechanic           VARCHAR(30)  NOT NULL DEFAULT '',
    instructions_pt    JSONB        NOT NULL DEFAULT '[]'::jsonb,
    instructions_en    JSONB        NOT NULL DEFAULT '[]'::jsonb,
    license_info       VARCHAR(255) NOT NULL DEFAULT 'Organização / Conteúdo Próprio',
    is_active          BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at         TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at         TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_exercise_catalog_global_source
    ON exercise_catalog (external_source, external_id)
    WHERE organization_id IS NULL AND external_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_exercise_catalog_org
    ON exercise_catalog (organization_id, is_active);

CREATE INDEX IF NOT EXISTS idx_exercise_catalog_filters
    ON exercise_catalog (primary_muscle, equipment, category)
    WHERE is_active = TRUE;

CREATE TABLE IF NOT EXISTS exercise_media (
    id                  UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    catalog_exercise_id UUID         NOT NULL REFERENCES exercise_catalog(id) ON DELETE CASCADE,
    organization_id     UUID         REFERENCES organizations(id) ON DELETE CASCADE,
    uploader_id         UUID         REFERENCES users(id) ON DELETE SET NULL,
    storage_key         TEXT         NOT NULL UNIQUE,
    filename            TEXT         NOT NULL DEFAULT '',
    media_type          VARCHAR(20)  NOT NULL CHECK (media_type IN ('VIDEO', 'IMAGE', 'GIF')),
    mime_type           VARCHAR(100) NOT NULL DEFAULT '',
    size_bytes          BIGINT       NOT NULL DEFAULT 0,
    status              VARCHAR(20)  NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'CONFIRMED')),
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_exercise_media_catalog
    ON exercise_media (catalog_exercise_id, status);

-- Vínculo opcional para transição da Fase 5 (Workout Builder) sem quebrar treinos legados
ALTER TABLE exercises
    ADD COLUMN IF NOT EXISTS catalog_exercise_id UUID REFERENCES exercise_catalog(id) ON DELETE SET NULL;

