    (NULL, 'free-exercise-db', 'Barbell_Bench_Press_-_Medium_Grip', 'Supino Reto com Barra', 'Barbell Bench Press - Medium Grip',
     'chest', '["shoulders","triceps"]'::jsonb, 'barbell', 'strength', 'beginner', 'push', 'compound',
     '["Deite-se no banco reto com os pés firmes no chão e pegada um pouco mais larga que os ombros.","Desça a barra de forma controlada até tocar levemente o meio do peitoral.","Empurre a barra de volta à posição inicial mantendo os ombros encaixados."]'::jsonb,
